struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  mass: f32,          // @default 6  m in ω = sqrt(k² + m²): the frequency even the longest mode never drops below
  speed: f32,         // @default 0.12  how fast field time runs against the clock
  amplitude: f32,     // @default 1  how far the field swings from zero
  foam: f32,          // @default 0.6  how much of the input noise rides on the modes as fine foam
  contours: f32,      // @default 3  iso-lines per unit of field value
  lineWidth: f32,     // @default 0.06  width of an iso-line, as a share of its spacing
  baseColor: vec4f,   // @default [0.006, 0.006, 0.02, 1]  the vacuum at rest
  crestColor: vec4f,  // @default [0.14, 0.07, 0.32, 1]  where the field swings positive
  troughColor: vec4f, // @default [0.03, 0.1, 0.22, 1]  where it swings negative
  lineColor: vec4f,   // @default [0.25, 0.3, 0.6, 1]  the iso-lines
  brightness: f32,    // @default 0.8  master gain on the field
  vignette: f32,      // @default 0.55  corner falloff
  grain: f32,         // @default 0.012  film grain
  planck: f32,        // @default 1  Planck foam: how hard spacetime itself fluctuates at the finest scale
  planckScale: f32,   // @default 0.0035  the stand-in Planck length, screen heights — the finest octave
  planckRate: f32,    // @default 6  how fast the foam boils
  foamColor: vec4f,   // @default [0.32, 0.28, 0.55, 1]  the foam's bubble walls
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

fn hash21(p: vec2f) -> f32 {
  var q = fract(p * vec2f(123.34, 456.21));
  q = q + dot(q, q + 45.32);
  return fract(q.x * q.y);
}

fn hash33(p: vec3f) -> vec3f {
  var q = fract(p * vec3f(0.1031, 0.1030, 0.0973));
  q = q + dot(q, q.yxz + 33.33);
  return fract((q.xxy + q.yxx) * q.zyx);
}


fn vnoise3(p: vec3f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = mix(hash33(i).x, hash33(i + vec3f(1.0, 0.0, 0.0)).x, u.x);
  let b = mix(hash33(i + vec3f(0.0, 1.0, 0.0)).x, hash33(i + vec3f(1.0, 1.0, 0.0)).x, u.x);
  let c = mix(hash33(i + vec3f(0.0, 0.0, 1.0)).x, hash33(i + vec3f(1.0, 0.0, 1.0)).x, u.x);
  let d = mix(hash33(i + vec3f(0.0, 1.0, 1.0)).x, hash33(i + vec3f(1.0, 1.0, 1.0)).x, u.x);
  return mix(mix(a, b, u.y), mix(c, d, u.y), u.z) * 2.0 - 1.0;
}

/// (displacement.xy in screen heights, bubble walls 0..1) at p, time t.
fn planckFoam(p: vec2f, t: f32, amount: f32, scale: f32, rate: f32) -> vec3f {
  var disp = vec2f(0.0);
  var walls = 0.0;
  let finest = max(scale, 0.0005);
  for (var o = 0; o < 5; o = o + 1) {
    // Octave 0 is 16 Planck lengths across, octave 4 is one.
    let len = finest * exp2(f32(4 - o));
    let q = p / len;
    // Smaller is faster: a fluctuation lasts about as long as light takes to cross it.
    let z = t * rate * exp2(f32(o) * 0.5);
    let w = exp2(f32(o) * 0.35);
    let nx = vnoise3(vec3f(q, z));
    let ny = vnoise3(vec3f(q + vec2f(31.7, 17.3), z + 5.1));
    disp = disp + vec2f(nx, ny) * len * w;
    if (o >= 3) {
      walls = walls + pow(1.0 - abs(nx), 14.0) * (0.5 + 0.5 * f32(o - 3));
    }
  }
  return vec3f(disp * amount * 0.35, walls * amount);
}

const MODES: i32 = 8;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let aspect = frameU.resolution.x / max(frameU.resolution.y, 1.0);
  let flat = (uv - vec2f(0.5)) * vec2f(aspect, 1.0);
  let pf = planckFoam(flat, frameU.absTime, params.planck, params.planckScale, params.planckRate);
  let p = flat + pf.xy;
  let t = frameU.absTime * params.speed;
  let m = max(params.mass, 0.0);

  // The modes: fixed wavevectors spread over directions and scales, phases from a hash.
  var phi = 0.0;
  for (var i = 0; i < MODES; i = i + 1) {
    let h = hash33(vec3f(f32(i) * 7.1, 3.3, 11.7));
    let kMag = mix(4.0, 26.0, h.x * h.x);
    let ang = h.y * 6.2831853;
    let k = kMag * vec2f(cos(ang), sin(ang));
    let omega = sqrt(kMag * kMag + m * m);
    // Equal energy per mode: amplitude ∝ 1/sqrt(ω), the vacuum's own spectrum.
    phi = phi + cos(dot(k, p) - omega * t + h.z * 6.2831853) / sqrt(omega);
  }
  phi = phi * 0.9;
  let foam = textureSample(inputTexture, inputSampler, uv).r - 0.5;
  phi = (phi + foam * params.foam) * params.amplitude;

  var col = params.baseColor.rgb;
  col = col + params.crestColor.rgb * max(phi, 0.0) * max(phi, 0.0) * 1.6;
  col = col + params.troughColor.rgb * max(-phi, 0.0) * max(-phi, 0.0) * 1.6;
  // Iso-lines at whole multiples of 1/contours, drawn only where the field is away from zero.
  let f = fract(phi * max(params.contours, 0.0));
  let line = 1.0 - smoothstep(0.0, max(params.lineWidth, 0.001), min(f, 1.0 - f));
  col = col + params.lineColor.rgb * line * 0.25 * smoothstep(0.0, 0.5, abs(phi));

  col = col + params.foamColor.rgb * pf.z * 0.35;

  let vig = 1.0 - clamp(params.vignette, 0.0, 1.0) * pow(length(flat) * 1.1, 2.2);
  let grain = (hash21(uv * frameU.resolution + vec2f(frameU.frameIndex * 7.13, frameU.frameIndex * 3.71)) - 0.5) * params.grain;
  return vec4f(max(col * params.brightness * vig + vec3f(grain), vec3f(0.0)), 1.0);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  rate: f32,          // @default 0.55  share of cycles in which a cell borrows a pair: how busy the vacuum is
  energy: f32,        // @default 1  scales every pair's ΔE: higher lives shorter and reaches less far (Δt ≈ ħ/2ΔE)
  lifetime: f32,      // @default 2.4  seconds one cell's cycle lasts at unit energy
  cell: f32,          // @default 0.17  size of a vacuum cell, in screen heights
  reach: f32,         // @default 0.75  how far apart a unit-energy pair gets, in cells
  bfield: f32,        // @default 2.4  magnetic field: radians a track curls over a life, opposite for the antiparticle
  jitter: f32,        // @default 0.02  how much the input noise shakes a pair's birthplace, screen heights
  size: f32,          // @default 0.0055  particle core radius, screen heights
  glow: f32,          // @default 1  particle brightness
  matterColor: vec4f, // @default [1.0, 0.5, 0.16, 1]  the particle
  antiColor: vec4f,   // @default [0.18, 0.72, 1.0, 1]  the antiparticle
  flashColor: vec4f,  // @default [0.9, 0.85, 1.0, 1]  the annihilation
  flash: f32,         // @default 0.7  brightness of the annihilation flash
  ripple: f32,        // @default 0.25  the ring the field rings with when a pair annihilates
  trail: f32,         // @default 0.9  how much of last frame's tracks survives into this one
  planck: f32,        // @default 1  Planck foam: how hard spacetime wrinkles under the tracks (match wgsl_field)
  planckScale: f32,   // @default 0.0035  the stand-in Planck length, screen heights (match wgsl_field)
  planckRate: f32,    // @default 6  how fast the foam boils (match wgsl_field)
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;

fn hash21(p: vec2f) -> f32 {
  var q = fract(p * vec2f(123.34, 456.21));
  q = q + dot(q, q + 45.32);
  return fract(q.x * q.y);
}

fn hash33(p: vec3f) -> vec3f {
  var q = fract(p * vec3f(0.1031, 0.1030, 0.0973));
  q = q + dot(q, q.yxz + 33.33);
  return fract((q.xxy + q.yxx) * q.zyx);
}


fn vnoise3(p: vec3f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = mix(hash33(i).x, hash33(i + vec3f(1.0, 0.0, 0.0)).x, u.x);
  let b = mix(hash33(i + vec3f(0.0, 1.0, 0.0)).x, hash33(i + vec3f(1.0, 1.0, 0.0)).x, u.x);
  let c = mix(hash33(i + vec3f(0.0, 0.0, 1.0)).x, hash33(i + vec3f(1.0, 0.0, 1.0)).x, u.x);
  let d = mix(hash33(i + vec3f(0.0, 1.0, 1.0)).x, hash33(i + vec3f(1.0, 1.0, 1.0)).x, u.x);
  return mix(mix(a, b, u.y), mix(c, d, u.y), u.z) * 2.0 - 1.0;
}

/// (displacement.xy in screen heights, bubble walls 0..1) at p, time t.
fn planckFoam(p: vec2f, t: f32, amount: f32, scale: f32, rate: f32) -> vec3f {
  var disp = vec2f(0.0);
  var walls = 0.0;
  let finest = max(scale, 0.0005);
  for (var o = 0; o < 5; o = o + 1) {
    // Octave 0 is 16 Planck lengths across, octave 4 is one.
    let len = finest * exp2(f32(4 - o));
    let q = p / len;
    // Smaller is faster: a fluctuation lasts about as long as light takes to cross it.
    let z = t * rate * exp2(f32(o) * 0.5);
    let w = exp2(f32(o) * 0.35);
    let nx = vnoise3(vec3f(q, z));
    let ny = vnoise3(vec3f(q + vec2f(31.7, 17.3), z + 5.1));
    disp = disp + vec2f(nx, ny) * len * w;
    if (o >= 3) {
      walls = walls + pow(1.0 - abs(nx), 14.0) * (0.5 + 0.5 * f32(o - 3));
    }
  }
  return vec3f(disp * amount * 0.35, walls * amount);
}

const FLASH_SECONDS: f32 = 0.45;

fn dir(a: f32) -> vec2f {
  return vec2f(cos(a), sin(a));
}

/// A particle: a hard core and a soft 1/r² halo.
fn spot(d: f32, r: f32) -> f32 {
  let x = d / r;
  return exp(-x * x) + 0.12 / (1.0 + x * x);
}

/// Distance from p to the segment a..b: a particle swept over one frame, so a fast one
/// leaves a line in the trails instead of a row of dots.
fn segment(p: vec2f, a: vec2f, b: vec2f) -> f32 {
  let ab = b - a;
  let t = clamp(dot(p - a, ab) / max(dot(ab, ab), 1e-8), 0.0, 1.0);
  return length(p - a - ab * t);
}

/// Where the pair stands at life fraction s: (particle, antiparticle).
fn pairAt(born: vec2f, s: f32, sep0: f32, theta: f32, curl0: f32) -> vec4f {
  let sep = sep0 * pow(sin(3.14159265 * clamp(s, 0.0, 1.0)), 0.8);
  let curl = curl0 * s;
  return vec4f(born + sep * dir(theta + curl), born - sep * dir(theta - curl));
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let aspect = frameU.resolution.x / max(frameU.resolution.y, 1.0);
  let flat = (uv - vec2f(0.5)) * vec2f(aspect, 1.0);
  // The tracks run through the same foam as the field: the point is displaced, not the pair.
  let p = flat + planckFoam(flat, frameU.absTime, params.planck, params.planckScale, params.planckRate).xy;
  let time = frameU.absTime;
  let cell = max(params.cell, 0.02);
  let energy = max(params.energy, 0.05);
  let cycle = max(params.lifetime, 0.05) / energy;
  let r = max(params.size, 0.0005);
  let home = vec2i(floor(p / cell));
  // One frame back, for the swept segments; a paused or first frame still draws a dot.
  let dt = clamp(frameU.deltaTime, 0.0, 0.1);

  var col = vec3f(0.0);
  for (var j = -2; j <= 2; j = j + 1) {
    for (var i = -2; i <= 2; i = i + 1) {
      let c = home + vec2i(i, j);
      let cf = vec2f(c);
      // Each cell runs its own clock, offset so the vacuum never pulses in step.
      let offset = hash21(cf + vec2f(17.0, 5.0)) * cycle;
      let local = time + offset;
      let k = floor(local / cycle);
      let tau = local - k * cycle;
      let h = hash33(vec3f(cf, k));
      let h2 = hash33(vec3f(cf + vec2f(91.0, 37.0), k));
      if (h.x >= params.rate) { continue; }

      // ΔE for this loan, in 1..2.5: the heavier the pair, the shorter and smaller its life.
      let e = 1.0 + 1.5 * h.y;
      let life = cycle * 0.5 / e;
      let start = h.z * (cycle - life - FLASH_SECONDS / energy);
      let age = tau - start;
      if (age < 0.0) { continue; }

      var born = (cf + vec2f(0.25) + 0.5 * h2.xy) * cell;
      let shake = textureSampleLevel(inputTexture, inputSampler, born / vec2f(aspect, 1.0) + vec2f(0.5), 0.0).r - 0.5;
      born = born + params.jitter * vec2f(shake, -shake);

      if (age < life) {
        let s = age / life;
        let sep0 = params.reach * cell / e;
        let theta = h2.z * 6.2831853;
        let curl0 = params.bfield * (0.6 + 0.8 * h2.x);
        let now = pairAt(born, s, sep0, theta, curl0);
        let before = pairAt(born, s - dt / life, sep0, theta, curl0);
        // They condense out of the field over the first tenth of a life.
        let fade = smoothstep(0.0, 0.1, s) * params.glow * (0.7 + 0.3 * e);
        col = col + params.matterColor.rgb * spot(segment(p, before.xy, now.xy), r) * fade;
        col = col + params.antiColor.rgb * spot(segment(p, before.zw, now.zw), r) * fade;
      } else {
        let u = (age - life) / (FLASH_SECONDS / energy);
        if (u < 1.0) {
          let d = length(p - born);
          let burst = exp(-u * 9.0) * spot(d, r * (1.0 + 0.8 * e));
          let radius = u * cell * 0.9;
          let ring = exp(-pow((d - radius) / (r * 0.9), 2.0)) * (1.0 - u) * (1.0 - u);
          col = col + params.flashColor.rgb * (burst * params.flash * e + ring * params.ripple);
        }
      }
    }
  }

  let size = vec2f(textureDimensions(inputTexture1));
  let prev = textureLoad(inputTexture1, vec2i(clamp(uv * size, vec2f(0.0), size - vec2f(1.0))), 0).rgb;
  col = max(col, prev * clamp(params.trail, 0.0, 0.99));
  return vec4f(col, 1.0);
}
